var autoHeight=()=>{const h=document.querySelectorAll("textarea[data-fls-input-autoheight]");if(h.length){let e=function(t,i){t.style.height=`${i}px`};h.forEach(t=>{const i=t.hasAttribute("data-fls-input-autoheight-min")?Number(t.dataset.flsInputAutoheightMin):Number(t.offsetHeight),n=t.hasAttribute("data-fls-input-autoheight-max")?Number(t.dataset.flsInputAutoheightMax):1/0;e(t,Math.min(i,n)),t.addEventListener("input",()=>{t.scrollHeight>i&&(t.style.height="auto",e(t,Math.min(Math.max(t.scrollHeight,i),n)))})})}};document.querySelector("textarea[data-fls-input-autoheight]")&&window.addEventListener("load",autoHeight);
